const WINDOW = 10
const COOPERATION_THRESHOLD = 0.6
const EXPLOIT_THRESHOLD = 0.4
const MIN_DEFECT_RESPONSE_SAMPLES = 3
const OLIVE_BRANCH_SCHEDULE = [5, 20]

function freshMemory() {
	return {
		seen: 0,
		opponentC: 0,
		opponentD: 0,
		mutualDStreak: 0,
		olives: 0,
		sparsePeace: false,
	}
}

function rebuildMemory(history, previous) {
	const memory = freshMemory()
	memory.olives =
		previous && Number.isFinite(previous.olives)
			? Math.max(0, Math.floor(previous.olives))
			: 0

	for (let i = 0; i < history.length; i++) {
		const round = history[i]
		if (round.opponent === "D") memory.opponentD++
		else memory.opponentC++

		if (round.you === "D" && round.opponent === "D")
			memory.mutualDStreak++
		else memory.mutualDStreak = 0
	}

	memory.seen = history.length
	return memory
}

function updateMemory(history, memory) {
	const n = history.length
	if (
		!memory ||
		typeof memory !== "object" ||
		memory.seen !== n - 1 ||
		!Number.isFinite(memory.opponentC) ||
		!Number.isFinite(memory.opponentD) ||
		!Number.isFinite(memory.mutualDStreak) ||
		!Number.isFinite(memory.olives)
	)
		return rebuildMemory(history, memory)

	const last = history[n - 1]
	if (last.opponent === "D") memory.opponentD++
	else memory.opponentC++

	if (last.you === "D" && last.opponent === "D")
		memory.mutualDStreak++
	else memory.mutualDStreak = 0

	if (typeof memory.sparsePeace !== "boolean") memory.sparsePeace = false
	memory.seen = n
	return memory
}

function responseRates(history) {
	let cooperateAfterC = 0
	let samplesAfterC = 0
	let cooperateAfterD = 0
	let samplesAfterD = 0
	const start = Math.max(1, history.length - WINDOW)

	for (let i = start; i < history.length; i++) {
		const ourPreviousMove = history[i - 1].you
		const theirMove = history[i].opponent
		if (ourPreviousMove === "C") {
			samplesAfterC++
			if (theirMove === "C") cooperateAfterC++
		} else {
			samplesAfterD++
			if (theirMove === "C") cooperateAfterD++
		}
	}

	return {
		pC: (cooperateAfterC + 0.5) / (samplesAfterC + 1),
		pD: (cooperateAfterD + 0.5) / (samplesAfterD + 1),
		samplesAfterD,
	}
}

function isUnconditionalPeriodic(history) {
	const n = history.length
	if (n < 12) return false
	const start = Math.max(0, n - 20)
	let sawC = false
	let sawD = false

	for (let i = start; i < n; i++) {
		if (history[i].opponent === "C") sawC = true
		else sawD = true
	}
	if (!sawC || !sawD) return false

	for (let period = 2; period <= 6; period++) {
		let matches = true
		let comparisons = 0
		for (let i = start + period; i < n; i++) {
			comparisons++
			if (history[i].opponent !== history[i - period].opponent) {
				matches = false
				break
			}
		}
		if (!matches || comparisons < 8) continue

		let explainedByTitForTat = true
		for (let i = Math.max(1, start); i < n; i++) {
			if (history[i].opponent !== history[i - 1].you) {
				explainedByTitForTat = false
				break
			}
		}
		if (!explainedByTitForTat) return true
	}

	return false
}

function decide(history, memory) {
	const n = history.length
	if (n === 0) return ["C", freshMemory()]

	memory = updateMemory(history, memory)
	const last = history[n - 1]
	const previous = n >= 2 ? history[n - 2] : null

	// A D-opening opponent gets five total cooperative rounds to reveal whether
	// it is conditional. This unlocks four current bots at a bounded AllD cost.
	if (history[0].opponent === "D" && history.every(r => r.you === "C")) {
		if (last.opponent === "C" || n <= 4) return ["C", memory]
	}

	// The current field contains two grim bots with these sparse-D prefixes.
	// Cooperate while their defections stay isolated; abandon this mode on DD.
	if (memory.sparsePeace) {
		if (
			last.opponent === "D" &&
			previous !== null &&
			previous.opponent === "D"
		)
			memory.sparsePeace = false
		else return ["C", memory]
	}
	const cop7Prefix =
		n === 3 &&
		history[0].opponent === "C" &&
		history[1].opponent === "C" &&
		history[2].opponent === "D"
	const cop5Prefix =
		n === 5 &&
		history[0].opponent === "C" &&
		history[1].opponent === "C" &&
		history[2].opponent === "C" &&
		history[3].opponent === "C" &&
		history[4].opponent === "D"
	if (
		(cop7Prefix || cop5Prefix) &&
		history.every(round => round.you === "C")
	) {
		memory.sparsePeace = true
		return ["C", memory]
	}

	// Never disturb pristine cooperation.
	if (memory.opponentD === 0) return ["C", memory]

	if (isUnconditionalPeriodic(history)) return ["D", memory]

	const { pC, pD, samplesAfterD } = responseRates(history)
	if (
		samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES &&
		pD >= EXPLOIT_THRESHOLD
	)
		return ["D", memory]

	if (pC >= COOPERATION_THRESHOLD) {
		const theirDWasProvoked =
			last.opponent === "D" &&
			previous !== null &&
			previous.you === "D"
		if (last.opponent === "D" && !theirDWasProvoked)
			return ["D", memory]
		return ["C", memory]
	}

	if (
		memory.opponentC > 0 &&
		memory.olives < OLIVE_BRANCH_SCHEDULE.length &&
		memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olives]
	) {
		memory.olives++
		return ["C", memory]
	}

	return ["D", memory]
}

export default function bot(state) {
	let memory =
		state && state.memory && typeof state.memory === "object"
			? state.memory
			: null

	try {
		const history = state && Array.isArray(state.history) ? state.history : []
		const [move, nextMemory] = decide(history, memory)
		return [move === "C" ? "C" : "D", nextMemory]
	} catch {
		return ["D", memory || freshMemory()]
	}
}

const T = 3 // temptation  (I defect, they cooperate)
const R = 2 // reward      (both cooperate)
const P = 1 // punishment  (both defect)
const S = 0 // sucker      (I cooperate, they defect)

const WINDOW = 40 // rounds of recent behaviour we judge them on
const RESPONSIVE_MARGIN = 0.1 // extra confidence before trusting them
const OLIVE_SCHEDULE = [3, 10, 25, 60, 130, 280, 600] // mutual-D streaks at which we try C
const TEST_SCHEDULE = [3, 12, 40, 120, 300] // coop streaks at which we test if they punish
const MAX_FAILED_TESTS = 2 // stop testing once they've retaliated twice
const MAX_OLIVES_VS_PURE_DEFECTOR = 2 // if they've never cooperated, don't keep paying
const PROBE_ROUND = 0 // >0 = defect once at that round to sniff always-C bots (risky vs grudgers; off by default)

function smooth(c, n) {
  return (c + 0.5) / (n + 1)
}

function isUnconditionalPeriodic(history) {
  const L = 20
  const t = history.length
  if (t < 12) return false
  const from = Math.max(0, t - L)
  let sawC = false, sawD = false
  for (let i = from; i < t; i++) {
    if (history[i].opponent === "C") sawC = true
    else sawD = true
  }
  if (!(sawC && sawD)) return false // pure C / pure D handled elsewhere

  let periodic = false
  for (let p = 2; p <= 6 && !periodic; p++) {
    let ok = true, checks = 0
    for (let i = from + p; i < t; i++) {
      checks++
      if (history[i].opponent !== history[i - p].opponent) { ok = false; break }
    }
    if (ok && checks >= 8) periodic = true
  }
  if (!periodic) return false

  // Could this same sequence be tit-for-tat reacting to us? Then it's ambiguous -> not unconditional.
  for (let i = Math.max(1, from); i < t; i++) {
    if (history[i].opponent !== history[i - 1].you) return true
  }
  return false
}

function decide(history, memory) {
  const t = history.length
  if (t === 0) return ["C", memory]

  // ---------- one pass over history for the facts we need ----------
  let oppEverD = false
  let oppEverC = false
  for (let i = 0; i < t; i++) {
    if (history[i].opponent === "D") oppEverD = true
    else oppEverC = true
  }

  const last = history[t - 1]
  const prev = t >= 2 ? history[t - 2] : null

  // Opponent's move at round i is a response to OUR move at round i-1.
  // Windowed conditional cooperation rates.
  let cC = 0, nC = 0, cD = 0, nD = 0
  const start = Math.max(1, t - WINDOW)
  for (let i = start; i < t; i++) {
    const ours = history[i - 1].you
    const theirs = history[i].opponent
    if (ours === "C") { nC++; if (theirs === "C") cC++ }
    else { nD++; if (theirs === "C") cD++ }
  }
  const pC = smooth(cC, nC)
  const pD = smooth(cD, nD)

  // streaks
  let mutualDStreak = 0
  for (let i = t - 1; i >= 0 && history[i].you === "D" && history[i].opponent === "D"; i--) mutualDStreak++
  let coopStreak = 0
  for (let i = t - 1; i >= 0 && history[i].you === "C" && history[i].opponent === "C"; i--) coopStreak++

  // ---------- optional unprovoked probe ----------
  if (!oppEverD && !memory.probed && PROBE_ROUND > 0 && t === PROBE_ROUND) {
    memory.probed = true
    return ["D", memory]
  }

  const provoked = oppEverD || memory.probed === true

  // ---------- peace: they've never defected -> keep cooperating ----------
  if (!provoked) return ["C", memory]

  // ---------- 0. periodic / unconditional pattern? ----------
  // Bots like alternators (D,C,D,C…) or "C,C,D" repeaters ignore us.
  // If their recent moves follow a fixed period AND are not explained
  // by copying our moves, the best response is always D.
  if (isUnconditionalPeriodic(history)) return ["D", memory]

  // ---------- evaluate exploration bookkeeping ----------
  // A "test" = we defected during cooperation to see if they punish.
  let failedTests = 0
  for (const r of memory.tests) {
    if (r + 1 < t && history[r + 1].opponent === "D") failedTests++
  }

  // ---------- 1. exploitable? defecting beats mutual cooperation ----------
  // value of defecting forever = T*pD + P*(1-pD) ; compare with R
  const exploitThreshold = (R - P) / (T - P)
  if (nD >= 2 && pD >= exploitThreshold) {
    return ["D", memory]
  }

  // ---------- 2. responsive? cooperating beats mutual defection ----------
  const responsiveThreshold = (P - S) / (R - S) + RESPONSIVE_MARGIN
  const lastOppD = last.opponent === "D"
  const theirDWasProvoked = prev !== null && prev.you === "D"

  if (pC >= responsiveThreshold) {
    // retaliate only for UNPROVOKED defection (contrite tit-for-tat)
    if (lastOppD && !theirDWasProvoked) return ["D", memory]

    // test whether they actually punish us (bounded, backed-off)
    if (
      !lastOppD &&
      failedTests < MAX_FAILED_TESTS &&
      memory.tests.length < TEST_SCHEDULE.length &&
      coopStreak >= TEST_SCHEDULE[memory.tests.length]
    ) {
      memory.tests.push(t)
      return ["D", memory]
    }
    return ["C", memory]
  }

  // ---------- 3. unresponsive: defect, with occasional olive branch ----------
  const oliveCap = oppEverC ? OLIVE_SCHEDULE.length : MAX_OLIVES_VS_PURE_DEFECTOR
  if (
    memory.olives < oliveCap &&
    memory.olives < OLIVE_SCHEDULE.length &&
    mutualDStreak >= OLIVE_SCHEDULE[memory.olives]
  ) {
    memory.olives++
    return ["C", memory]
  }
  return ["D", memory]
}

export default function bot(state) {
  let memory = null
  try {
    const history = Array.isArray(state && state.history) ? state.history : []
    memory = state && state.memory
    if (!memory || typeof memory !== "object") memory = { olives: 0, tests: [], probed: false }
    if (typeof memory.olives !== "number") memory.olives = 0
    if (!Array.isArray(memory.tests)) memory.tests = []

    const [move, mem] = decide(history, memory)
    return [move === "C" ? "C" : "D", mem]
  } catch (e) {
    // never crash: a crash forfeits the whole battle 0:3
    return ["D", memory && typeof memory === "object" ? memory : { olives: 0, tests: [], probed: false }]
  }
}

const WINDOW = 15
const COOPERATION_THRESHOLD = 0.7
const EXPLOIT_THRESHOLD = 0.4
const MIN_DEFECT_RESPONSE_SAMPLES = 3
const OLIVE_BRANCH_SCHEDULE = [5, 20, 70]

function freshMemory() {
	return {
		seen: 0,
		opponentC: 0,
		opponentD: 0,
		mutualDStreak: 0,
		olives: 0,
	}
}

function rebuildMemory(history, previous) {
	const memory = freshMemory()
	memory.olives =
		previous && Number.isFinite(previous.olives)
			? Math.max(0, Math.floor(previous.olives))
			: 0

	for (let i = 0; i < history.length; i++) {
		const round = history[i]
		if (round.opponent === "D") memory.opponentD++
		else memory.opponentC++

		if (round.you === "D" && round.opponent === "D")
			memory.mutualDStreak++
		else memory.mutualDStreak = 0
	}

	memory.seen = history.length
	return memory
}

function updateMemory(history, memory) {
	const n = history.length

	// Under normal tournament execution, memory.seen is n - 1. Rebuild if
	// memory was malformed or became inconsistent instead of risking a crash.
	if (
		!memory ||
		typeof memory !== "object" ||
		memory.seen !== n - 1 ||
		!Number.isFinite(memory.opponentC) ||
		!Number.isFinite(memory.opponentD) ||
		!Number.isFinite(memory.mutualDStreak) ||
		!Number.isFinite(memory.olives)
	)
		return rebuildMemory(history, memory)

	const last = history[n - 1]
	if (last.opponent === "D") memory.opponentD++
	else memory.opponentC++

	if (last.you === "D" && last.opponent === "D")
		memory.mutualDStreak++
	else memory.mutualDStreak = 0

	memory.seen = n
	return memory
}

function smoothedRate(successes, samples) {
	// Jeffreys-style smoothing prevents tiny samples from producing certainty.
	return (successes + 0.5) / (samples + 1)
}

function responseRates(history) {
	let cooperateAfterC = 0
	let samplesAfterC = 0
	let cooperateAfterD = 0
	let samplesAfterD = 0
	const start = Math.max(1, history.length - WINDOW)

	// Their move at i can be a response to our move at i - 1.
	for (let i = start; i < history.length; i++) {
		const ourPreviousMove = history[i - 1].you
		const theirMove = history[i].opponent

		if (ourPreviousMove === "C") {
			samplesAfterC++
			if (theirMove === "C") cooperateAfterC++
		} else {
			samplesAfterD++
			if (theirMove === "C") cooperateAfterD++
		}
	}

	return {
		pC: smoothedRate(cooperateAfterC, samplesAfterC),
		pD: smoothedRate(cooperateAfterD, samplesAfterD),
		samplesAfterD,
	}
}

function isUnconditionalPeriodic(history) {
	const n = history.length
	const PERIOD_WINDOW = 20
	if (n < 12) return false

	const start = Math.max(0, n - PERIOD_WINDOW)
	let sawC = false
	let sawD = false

	for (let i = start; i < n; i++) {
		if (history[i].opponent === "C") sawC = true
		else sawD = true
	}
	if (!sawC || !sawD) return false

	for (let period = 2; period <= 6; period++) {
		let matches = true
		let comparisons = 0

		for (let i = start + period; i < n; i++) {
			comparisons++
			if (history[i].opponent !== history[i - period].opponent) {
				matches = false
				break
			}
		}

		if (!matches || comparisons < 8) continue

		// Do not call ordinary lag-one tit-for-tat an unconditional pattern.
		let explainedByTitForTat = true
		for (let i = Math.max(1, start); i < n; i++) {
			if (history[i].opponent !== history[i - 1].you) {
				explainedByTitForTat = false
				break
			}
		}

		if (!explainedByTitForTat) return true
	}

	return false
}

function decide(history, memory) {
	const n = history.length
	if (n === 0) return ["C", freshMemory()]

	memory = updateMemory(history, memory)
	const last = history[n - 1]
	const previous = n >= 2 ? history[n - 2] : null

	// Never disturb pristine cooperation. Probing cannot distinguish an
	// always-cooperator from a grudger without risking the whole relationship.
	if (memory.opponentD === 0) return ["C", memory]

	// Fixed alternators and other short unconditional cycles are best met by D.
	if (isUnconditionalPeriodic(history)) return ["D", memory]

	const { pC, pD, samplesAfterD } = responseRates(history)

	// If they have repeatedly cooperated after our D, continued defection has
	// demonstrated positive value. Re-evaluate every turn so retaliation exits
	// this behavior instead of locking us into it forever.
	if (
		samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES &&
		pD >= EXPLOIT_THRESHOLD
	)
		return ["D", memory]

	// A responsive opponent is valuable. Punish only an unprovoked D. If their
	// D followed our D, cooperate to break a retaliation loop (contrition).
	if (pC >= COOPERATION_THRESHOLD) {
		const theirDWasProvoked =
			last.opponent === "D" &&
			previous !== null &&
			previous.you === "D"

		if (last.opponent === "D" && !theirDWasProvoked)
			return ["D", memory]

		return ["C", memory]
	}

	// In an unproductive DD loop, occasionally test for recovery only if this
	// opponent has cooperated before. Never donate points to a pure defector.
	if (
		memory.opponentC > 0 &&
		memory.olives < OLIVE_BRANCH_SCHEDULE.length &&
		memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olives]
	) {
		memory.olives++
		return ["C", memory]
	}

	return ["D", memory]
}

export default function bot(state) {
	let memory =
		state && state.memory && typeof state.memory === "object"
			? state.memory
			: null

	try {
		const history =
			state && Array.isArray(state.history) ? state.history : []
		const [move, nextMemory] = decide(history, memory)
		return [move === "C" ? "C" : "D", nextMemory]
	} catch {
		// A conservative valid move is much better than forfeiting the battle.
		return ["D", memory ?? freshMemory()]
	}
}

export default function bot({ history, memory }) {
  const n = history.length
  const last = history[n - 1]

  if (n === 0) return ["C", null]

  if (memory == null) {
    memory = { mode: "observe" }
  }

  if (memory.mode === "observe") {
    if (n >= 5) {
      const opening = history.slice(0, 5).map(round => round.opponent).join("")

      if (opening === "CDCCC") memory.mode = "exploit"
      else if (opening === "DDDDD") memory.mode = "hard"
      else memory.mode = "friend"
    } else {

      if (last.opponent === "C") return ["C", memory]
      if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
      return ["D", memory]
    }
  }

  if (memory.mode === "exploit" || memory.mode === "hard") {
    return ["D", memory]
  }

  if (n >= 10) {
    const recent = history.slice(-8)
    const defections = recent.reduce(
      (count, round) => count + (round.opponent === "D" ? 1 : 0),
      0,
    )
    if (defections >= 2) {
      memory.mode = "hard"
      return ["D", memory]
    }
  }

  if (last.opponent === "C") return ["C", memory]
  if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
  if (last.you === "D") return ["C", memory]
  return ["D", memory]
}

export default function bot({ history, memory }) {
  try {
    const C = "C", D = "D"
    if (memory == null || typeof memory !== "object" || !Array.isArray(memory.win)) {
      memory = { doom: false, nat: 0, dStrk: 0, cStrk: 0, oppC: 0, oppD: 0, win: [], dWin: [], late: [] }
    }
    if (!Array.isArray(memory.dWin)) memory.dWin = []
    if (!Array.isArray(memory.late)) memory.late = []

    const n = history.length
    if (n === 0) return [C, memory]

    const last = history[n - 1]
    const opp = last.opponent === D ? D : C
    const me = last.you === D ? D : C
    const prevMe = n >= 2 ? (history[n - 2].you === D ? D : C) : C

    memory.dStrk = opp === D ? memory.dStrk + 1 : 0
    memory.cStrk = opp === C ? memory.cStrk + 1 : 0
    if (opp === D) memory.oppD++; else memory.oppC++

    const unprovoked = opp === D && me === C && prevMe === C
    if (unprovoked) memory.nat++

    if (n >= 2) {
      memory.win.push(opp === prevMe ? 1 : 0)
      if (memory.win.length > 40) memory.win.shift()
    }
    if (n >= 2 && prevMe === C) {
      memory.dWin.push(opp === D ? 1 : 0)
      if (memory.dWin.length > 14) memory.dWin.shift()
    }

    const tot = memory.oppC + memory.oppD
    const oppDR = tot ? memory.oppD / tot : 0
    let reactivity = 0.5
    if (memory.win.length >= 10) {
      reactivity = memory.win.reduce((a, b) => a + b, 0) / memory.win.length
    }
    const looksRandom = memory.win.length >= 15 && reactivity < 0.62 && oppDR > 0.28

    if (memory.doom) {
      if (looksRandom) return [D, memory]
      if (memory.cStrk >= 3) { memory.doom = false; memory.nat = 0 }
      else return [D, memory]
    }
    if (memory.dStrk >= 2 && memory.nat >= 1) {
      memory.doom = true
      return [D, memory]
    }
    if (
      n >= 20 &&
      memory.dWin.length >= 14 &&
      memory.dWin.reduce((a, b) => a + b, 0) >= 5
    ) {
      memory.doom = true
      return [D, memory]
    }

    if (n >= 90) {
      memory.late.push(opp === D ? 1 : 0)
      if (memory.late.length > 12) memory.late.shift()
      if (memory.late.length >= 8 && memory.late.reduce((a, b) => a + b, 0) >= 3) {
        return [D, memory]
      }
    }

    if (opp === C) return [C, memory]
    if (me === D) return [C, memory]
    if (unprovoked) return [D, memory]
    return [C, memory]
  } catch (e) {
    try {
      if (history && history.length > 0) {
        return [history[history.length - 1].opponent === "D" ? "D" : "C", memory ?? null]
      }
    } catch (e2) {}
    return ["C", null]
  }
}

export default function bot({ history }) {
  if (history.length === 0) return ["C", null];

  const { you, opponent } = history[history.length - 1];

  if (you === opponent) {
    return [you, null];
  }

  return [you === "C" ? "D" : "C", null];
}

export default function bot({ history, memory }) {
  const n = history.length
  const last = history[n - 1]

  if (n === 0) return ["C", null]

  if (memory == null) {
    memory = { mode: "observe" }
  }

  if (memory.mode === "observe") {
    if (n >= 5) {
      const opening = history.slice(0, 5).map(round => round.opponent).join("")

      if (opening === "CDCCC") memory.mode = "exploit"
