export default function bot({history, memory}) {
    const round = history.length;
    if (round === 0) return ["C", initMemory()];
    const m = memory ?? initMemory();
    const last = history.at(-1);
    const lastOpponentMove = last.opponent;
    m.recent.push(lastOpponentMove);
    if (m.recent.length > 3) m.recent.shift();
    const shortDefectRate =
        m.recent.length > 0
            ? m.recent.filter(x => x === "D").length / m.recent.length
            : 0;
    m.coopStreak = lastOpponentMove === "C" ? m.coopStreak + 1 : 0;
    const payoff = payoffOf(last.you, last.opponent);
    m.payoffs.push(payoff);
    if (m.payoffs.length > 6) m.payoffs.shift();
    const avgPayoff = m.payoffs.reduce((a, b) => a + b, 0) / m.payoffs.length;
    if (m.testPending > 0) {
        m.testPending--;
        if (m.testPending === 0) {
            if (lastOpponentMove === "C") {
                m.confirmedSoft = true;
                m.retaliatory = false;
            } else {
                m.confirmedSoft = false;
                m.retaliatory = true;
            }
        }
    }
    const TEST_THRESHOLD = 70;
    const RETEST_THRESHOLD = 20;
    let move;
    if (m.payoffs.length >= 4 && avgPayoff <= 0.8) {
        move = "D";
        m.confirmedSoft = false;
    } else if (m.confirmedSoft) {
        if (lastOpponentMove === "D") {
            m.confirmedSoft = false;
            move = "D";
        } else {
            move = "D";
        }
    } else if (shortDefectRate >= 0.5) {
        move = lastOpponentMove === "D" ? "D" : "C";
    } else if (m.testPending === 0 && m.coopStreak >= (m.retaliatory ? RETEST_THRESHOLD : TEST_THRESHOLD)) {
        move = "D";
        m.testPending = 2;
    } else if (lastOpponentMove === "D") {
        move = Math.random() < 0.4 ? "C" : "D";
    } else {
        move = "C";
    }

	return [move, m] // Move must come 1st, then memory 2nd
}

function payoffOf(you, opp) {
    if (you === "C" && opp === "C") return 2;
    if (you === "D" && opp === "C") return 3;
    if (you === "C" && opp === "D") return 0;
    return 1;
}

function initMemory() {
    return {
        recent: [],
        coopStreak: 0,
        payoffs: [],
        confirmedSoft: false,
        retaliatory: false,
        testPending: 0
    };
}

export default function bot({ history, memory }) {
  const C = "C", D = "D";

  const init = () => ({
    oppC: 0,
    oppD: 0,
    score: 0,
    mode: "probe",
    punish: 0,
    exploit: 0,
    olive: 0,
    testIdx: 0,
    failedTests: 0,
    lastTestRound: -999,
    everDefected: false,
    hardLock: false,
    cooldown: 0,
    chaos: 0
  });

  try {
    memory = memory && typeof memory === "object" ? memory : init();
    const n = history.length;
    if (n === 0) return [C, memory];

    const last = history[n - 1];
    const myLast = last.you === D ? D : C;
    const oppLast = last.opponent === D ? D : C;

    if (oppLast === C) memory.oppC++;
    else memory.oppD++;

    memory.score +=
      myLast === C && oppLast === C ? 2 :
      myLast === D && oppLast === C ? 3 :
      myLast === C && oppLast === D ? 0 : 1;

    if (myLast === D) memory.everDefected = true;

    if (n >= 2) {
      const p = history[n - 2].opponent === D ? 1 : 0;
      const q = oppLast === D ? 1 : 0;
      if (p !== q) memory.chaos = Math.min(memory.chaos + 1, 100);
      else memory.chaos = Math.max(memory.chaos - 1, 0);
    }

    const total = memory.oppC + memory.oppD;
    const defRate = total ? memory.oppD / total : 0;
    const coopRate = 1 - defRate;
    const avg = memory.score / n;
    const noisy = n >= 18 && memory.chaos >= 10 && defRate > 0.2 && defRate < 0.8;

    if (memory.cooldown > 0) memory.cooldown--;
    if (memory.punish > 0) memory.punish--;

    if (n < 6) {
      const open = [C, C, D, C, C, D];
      return [open[n], memory];
    }

    let dd = 0;
    for (let i = n - 1; i >= 0 && i >= n - 10; i--) {
      if (history[i].you === D && history[i].opponent === D) dd++;
      else break;
    }

    if (
      defRate > 0.72 ||
      (n >= 20 && avg < 0.9) ||
      (noisy && defRate > 0.45)
    ) memory.hardLock = true;

    if (memory.hardLock) {
      if (coopRate > 0.52 && n % 17 === 0) return [C, memory];
      if (coopRate > 0.62 && memory.oppC > memory.oppD + 4) memory.hardLock = false;
      else return [D, memory];
    }

    if (memory.exploit > 0) {
      if (oppLast === D) memory.exploit = 0;
      else return [D, memory];
    }

    if (
      n >= 8 &&
      defRate < 0.05 &&
      memory.everDefected
    ) {
      memory.exploit = 1;
      return [D, memory];
    }

    const testSchedule = [4, 12, 30, 70, 160];
    if (
      memory.failedTests < 2 &&
      memory.testIdx < testSchedule.length &&
      n - memory.lastTestRound > 12 &&
      oppLast === C &&
      defRate < 0.35
    ) {
      const coopStreakNeeded = testSchedule[memory.testIdx];
      let cc = 0;
      for (let i = n - 1; i >= 0; i--) {
        if (history[i].you === C && history[i].opponent === C) cc++;
        else break;
      }
      if (cc >= coopStreakNeeded) {
        memory.lastTestRound = n;
        memory.testIdx++;
        memory.punish = 1;
        return [D, memory];
      }
    }

    if (n >= 2 && history[n - 2].you === D && oppLast === D) {
      memory.failedTests++;
    }

    if (dd >= 4 && memory.cooldown === 0 && defRate < 0.6) {
      memory.cooldown = 7;
      return [C, memory];
    }

    if (oppLast === D) {
      if (memory.punish > 0 && defRate < 0.55) return [C, memory];
      if (defRate > 0.55) return [D, memory];
      if (n % 3 === 0 && defRate < 0.35) return [C, memory];
      return [D, memory];
    }

    if (n >= 96) {
      if (defRate < 0.08) return [D, memory];
      if (defRate > 0.5) return [D, memory];
    }

    return [C, memory];
  } catch {
    const safe = {
      oppC: 0, oppD: 0, score: 0, mode: "probe", punish: 0, exploit: 0,
      olive: 0, testIdx: 0, failedTests: 0, lastTestRound: -999,
      everDefected: false, hardLock: true, cooldown: 0, chaos: 0
    };
    if (history && history.length) {
      const opp = history[history.length - 1].opponent === "D" ? "D" : "C";
      return [opp, safe];
    }
    return [D, safe];
  }
}

// MAXIMUM BEST BOT
// Strategy: classify the opponent's behavior pattern, then pick the
// counter-strategy that scores best against that specific pattern.
//
// - vs bots that (almost) always cooperate  -> exploit hard (mostly defect)
// - vs bots that (almost) always defect     -> defect back, cut losses
// - vs random-ish bots                       -> defect (higher EV than cooperating)
// - vs reactive bots (tit-for-tat-like)      -> cooperate, forgive slips
// - vs grudgers (punish forever after 1 D)   -> never defect first, stay clean
// - unclear / early game                     -> generous tit-for-tat

export default function bot({ history, memory }) {
  memory = memory ?? {
    probeRound: null, // round index where we last threw an exploit probe
  }

  const round = history.length

  // --- First move: always cooperate to open the door for trust ---
  if (round === 0) return ["C", memory]

  const lastOpp = history.at(-1).opponent

  // --- Early game: plain generous tit-for-tat while we gather data.
  //     Widened from 10 -> 25 rounds: a "reactive" read off <10 points was
  //     noise, not signal, and locked us out of exploiting a real pushover. ---
  if (round < 25) {
    const forgive = lastOpp === "D" && Math.random() < 0.15
    return [lastOpp === "D" && !forgive ? "D" : "C", memory]
  }

  // --- Stats over full history ---
  const oppDefects = history.filter(m => m.opponent === "D").length
  const oppDefectRate = oppDefects / round

  // Grudger signature: after our first defection, does opponent basically
  // never cooperate again?
  const firstOurDefectIdx = history.findIndex(m => m.you === "D")
  let grudgerLike = false
  if (firstOurDefectIdx !== -1 && firstOurDefectIdx < round - 5) {
    const after = history.slice(firstOurDefectIdx + 1)
    const defectsAfter = after.filter(m => m.opponent === "D").length
    grudgerLike = defectsAfter / after.length > 0.9
  }

  // Reactive signature: correlate opponent's move with OUR previous move,
  // using only the LAST 30 rounds (sliding window) so a stale or lucky
  // early read can't lock us in forever, and require a real sample size.
  const windowStart = Math.max(1, history.length - 30)
  let matches = 0
  let checked = 0
  for (let i = windowStart; i < history.length; i++) {
    const ourPrev = history[i - 1].you
    const oppNow = history[i].opponent
    checked++
    if (ourPrev === oppNow) matches++
  }
  const reactivity = checked >= 15 ? matches / checked : 0.5 // not enough data => don't trust it

  // --- Classification & response ---

  // 1) Near-total cooperator: exploit, but not 100% of the time
  if (oppDefectRate < 0.05) {
    return [round % 5 === 0 ? "C" : "D", memory]
  }

  // 2) Near-total defector: minimize damage, don't get exploited
  if (oppDefectRate > 0.6) {
    return ["D", memory]
  }

  // 3) Grudger-like: never poke the bear
  if (grudgerLike) {
    return ["C", memory]
  }

  // 4) Reactive/tit-for-tat-like with a decent-sized sample: cooperate,
  //    forgive occasional defections, but periodically probe (every ~40
  //    rounds) with a single defection to check whether the "reactive" read
  //    is still accurate and whether exploitation has become safe (e.g. a
  //    bot that's actually soft and stopped punishing). If the probe gets
  //    punished, we're back to normal next round via lastOpp handling above.
  if (checked >= 15 && reactivity > 0.7) {
    const dueForProbe =
      memory.probeRound === null || round - memory.probeRound >= 40
    if (dueForProbe && lastOpp !== "D") {
      memory.probeRound = round
      return ["D", memory]
    }
    const forgive = lastOpp === "D" && Math.random() < 0.2
    return [lastOpp === "D" && !forgive ? "D" : "C", memory]
  }

  // 5) Roughly random / unclear pattern: defect has higher expected value
  if (checked >= 15 && reactivity < 0.3) {
    return ["D", memory]
  }

  // 6) Default fallback: generous tit-for-tat
  const forgive = lastOpp === "D" && Math.random() < 0.15
  return [lastOpp === "D" && !forgive ? "D" : "C", memory]
}

export default state => {
    const memory = state.memory;
    const history = state.history;

    const opp_d_stats = history.filter(h => h.opponent === "D").length;
    const opp_c_stats = history.filter(h => h.opponent === "C").length;

    const total_stats = opp_d_stats + opp_c_stats;

    if (total_stats === 0) {
        return ["C", memory]; //Start of friendly
    }

    if (opp_c_stats / total_stats > 0.5 && (total_stats < 100 || Math.random() < 0.5 )) { //At the end of the game, hammer out defects so that we get just a few more points than the opponent
        return ["C", memory]; //Cooperate if opponent cooperates more than 50% of the time
    }

    return ["D", memory]; //Fallback to defection
}

/**
 * APEX — Adaptive Prisoner's EXpert
 *
 * Strategy architecture (in order of priority):
 *
 * 1. OPPONENT CLASSIFICATION
 *    Continuously classify the opponent into one of several archetypes
 *    based on their behavioural fingerprint in the history so far.
 *
 * 2. ADAPTIVE RESPONSE
 *    Choose a response mode tailored to the detected archetype:
 *    - ALWAYS_DEFECT  → mirror defect (cut losses, earn mutual 1/round)
 *    - ALWAYS_COOPERATE → cooperate almost always; probe once mid-game
 *    - TFT / REACTIVE → cooperate; use Gradual punishment on defections
 *    - RANDOM         → use Tit-for-Two-Tats (forgive single noise)
 *    - GRUDGER        → never provoke; full cooperation
 *    - UNKNOWN        → Gradual (best robust default)
 *
 * 3. GRADUAL PUNISHMENT (core engine)
 *    After the n-th cumulative defection by the opponent, punish with
 *    exactly n consecutive defections, then calm down with 2 cooperations.
 *    This is proportional, memorable, and de-escalating — the strategy
 *    that consistently beats TFT in large-scale tournaments.
 *
 * 4. ENDGAME DEFECTION
 *    In the final ~5 rounds (estimated from round count ≥ 100), defect
 *    against cooperating opponents to squeeze extra points. Risky against
 *    reactive opponents, so only trigger against confirmed cooperators
 *    or once we're deep enough that retaliation cost is minimal.
 *
 * 5. PROBE EXPLOITATION
 *    Against confirmed always-cooperators, defect once around round 30
 *    to test if they retaliate. If they don't, defect regularly (every
 *    ~5 rounds) for free points. If they do, switch to TFT mode.
 */

export default function bot({ history, memory }) {
  // ── Initialise memory ──────────────────────────────────────────────
  memory = memory ?? {
    // Gradual state
    punishRemaining: 0,   // how many more D's to fire in current punishment
    calmRemaining: 0,     // how many more C's in the calming period after punishment
    defectCount: 0,       // total opponent defections seen (= punishment severity counter)

    // Opponent classification
    opponentType: "UNKNOWN", // ALWAYS_DEFECT | ALWAYS_COOPERATE | TFT | RANDOM | GRUDGER | UNKNOWN
    classifiedAt: -1,        // round at which we locked in a classification

    // Exploitation state (for ALWAYS_COOPERATE)
    probedAt: -1,            // round we sent our exploit probe
    exploitMode: false,      // currently exploiting a confirmed pushover

    // Endgame
    endgameStarted: false,
  }

  const round = history.length

  // ── First move: always cooperate ───────────────────────────────────
  if (round === 0) return ["C", memory]

  // ── Update defect count from last opponent move ────────────────────
  const lastOpp = history[round - 1].opponent
  if (lastOpp === "D") memory.defectCount++

  // ── Opponent classification ────────────────────────────────────────
  // Re-classify every 10 rounds until we're confident, then lock in.
  if (round >= 5 && (memory.classifiedAt === -1 || round % 10 === 0) && round <= 80) {
    memory.opponentType = classify(history, round)
    memory.classifiedAt = round
  }

  // ── Endgame logic ─────────────────────────────────────────────────
  // The game runs "at least 100 rounds". We don't know the exact end,
  // so we start being opportunistic from round 95 onward only against
  // opponents who we believe won't retaliate (always-cooperate / grudger
  // already triggered). Against reactive opponents, no endgame defection
  // — the retaliation cost outweighs the gain with unknown rounds left.
  if (round >= 95 && !memory.endgameStarted) {
    if (memory.opponentType === "ALWAYS_COOPERATE" || memory.exploitMode) {
      memory.endgameStarted = true
    }
  }
  if (memory.endgameStarted) {
    return ["D", memory]
  }

  // ── Response by archetype ──────────────────────────────────────────
  const type = memory.opponentType

  // ALWAYS_DEFECT: lock into mutual defection — 1 pt each is better than
  // being exploited for 0 pts while they get 3.
  if (type === "ALWAYS_DEFECT") {
    return ["D", memory]
  }

  // ALWAYS_COOPERATE: mostly cooperate, probe once at round ~30 to confirm,
  // then exploit every few rounds.
  if (type === "ALWAYS_COOPERATE") {
    if (memory.probedAt === -1 && round >= 20) {
      // Send a probe defection
      memory.probedAt = round
      return ["D", memory]
    }
    if (memory.probedAt > 0) {
      const roundsAfterProbe = round - memory.probedAt
      if (roundsAfterProbe >= 2) {
        // Check if they retaliated after our probe
        const theyRetaliated = history
          .slice(memory.probedAt)
          .some(m => m.opponent === "D")
        if (!theyRetaliated) {
          // Confirmed pushover: exploit every 4 rounds
          memory.exploitMode = true
          if (round % 4 === 0) return ["D", memory]
          return ["C", memory]
        } else {
          // They punished — reclassify away from ALWAYS_COOPERATE
          memory.opponentType = "TFT"
          memory.probedAt = -1
        }
      }
    }
    return ["C", memory]
  }

  // RANDOM: use Tit-for-Two-Tats — only defect after two consecutive
  // opponent defections. This avoids noise-triggered escalation spirals.
  if (type === "RANDOM") {
    if (round >= 2) {
      const lastTwo = history.slice(-2)
      if (lastTwo[0].opponent === "D" && lastTwo[1].opponent === "D") {
        return ["D", memory]
      }
    }
    return ["C", memory]
  }

  // GRUDGER: they'll never forgive a single defection, so never defect.
  if (type === "GRUDGER") {
    return ["C", memory]
  }

  // TFT / UNKNOWN / REACTIVE: use Gradual strategy.
  // Gradual cooperates by default; when the opponent has defected n times
  // total, it punishes with n defections then 2 calming cooperations.
  return gradual(lastOpp, memory)
}

// ── Gradual engine ────────────────────────────────────────────────────
function gradual(lastOpp, memory) {
  // Currently in punishment phase
  if (memory.punishRemaining > 0) {
    memory.punishRemaining--
    return ["D", memory]
  }

  // Currently in calming phase
  if (memory.calmRemaining > 0) {
    memory.calmRemaining--
    return ["C", memory]
  }

  // Opponent just defected — start punishment
  if (lastOpp === "D") {
    // Punish with defectCount defections (already incremented above)
    const punishes = memory.defectCount
    if (punishes <= 1) {
      // First defection: punish once, then calm with 2 C's
      memory.punishRemaining = 0   // we fire this round as the 1st punch
      memory.calmRemaining = 2
      return ["D", memory]
    } else {
      // n-th defection: punish n times (first punch now, n-1 deferred)
      memory.punishRemaining = punishes - 1
      memory.calmRemaining = 2
      return ["D", memory]
    }
  }

  // Default: cooperate
  return ["C", memory]
}

// ── Classifier ────────────────────────────────────────────────────────
function classify(history, round) {
  const oppMoves = history.map(m => m.opponent)
  const total = oppMoves.length
  const dCount = oppMoves.filter(m => m === "D").length
  const cCount = total - dCount
  const defectRate = dCount / total

  // Always defect: ≥90% D's
  if (defectRate >= 0.9) return "ALWAYS_DEFECT"

  // Always cooperate: ≥95% C's
  if (defectRate <= 0.05) return "ALWAYS_COOPERATE"

  // Grudger: cooperated solidly until a single defection, then only D's
  // Signature: all C's up to some point, then all D's
  if (dCount >= 3 && cCount >= 3) {
    const firstD = oppMoves.indexOf("D")
    if (firstD >= 3) {
      const afterFirstD = oppMoves.slice(firstD)
      const allDefectAfter = afterFirstD.every(m => m === "D")
      if (allDefectAfter && afterFirstD.length >= 3) return "GRUDGER"
    }
  }

  // TFT / reactive: opponent's move correlates with OUR previous move
  if (round >= 10) {
    let tftMatches = 0
    for (let i = 1; i < history.length; i++) {
      if (history[i].opponent === history[i - 1].you) tftMatches++
    }
    const tftRate = tftMatches / (history.length - 1)
    if (tftRate >= 0.8) return "TFT"
  }

  // Random: high variance, no strong pattern
  if (defectRate > 0.25 && defectRate < 0.75) {
    // Check for alternating or random patterns
    let switches = 0
    for (let i = 1; i < oppMoves.length; i++) {
      if (oppMoves[i] !== oppMoves[i - 1]) switches++
    }
    const switchRate = switches / (oppMoves.length - 1)
    if (switchRate > 0.35) return "RANDOM"
  }

  return "UNKNOWN"
}

export default function bot(state) {
  try {
    const history = state?.history || [];
    const t = history.length;

    // 1. Initialize robust memory
    let mem = state?.memory;
    if (!mem || typeof mem !== "object") {
      mem = {
        // Transition tracking for deeper analysis
        transitions: {
          CC: { c: 2, d: 0 }, // Heavily bias initial trust (start optimistic)
          CD: { c: 1, d: 1 },
          DC: { c: 2, d: 0 },
          DD: { c: 0, d: 2 }
        },
        consecutiveOpponentDefects: 0,
        totalOpponentDefects: 0,
        mode: "TRUST" // 'TRUST', 'DEFEND'
      };
    }

    // Round 0: Always trust and cooperate
    if (t === 0) return ["C", mem];

    const lastRound = history[t - 1];
    const oppLast = lastRound.opponent;
    const youLast = lastRound.you;
    const prevRound = t >= 2 ? history[t - 2] : null;

    // Track statistics
    if (oppLast === "D") {
      mem.consecutiveOpponentDefects++;
      mem.totalOpponentDefects++;
    } else {
      mem.consecutiveOpponentDefects = 0;
    }

    // 2. Incremental Transition Update
    if (prevRound) {
      const prevStateKey = prevRound.you + prevRound.opponent;
      if (mem.transitions[prevStateKey]) {
        if (oppLast === "C") mem.transitions[prevStateKey].c++;
        else mem.transitions[prevStateKey].d++;
      }
    }

    // 3. Absolute Hard Defense: Only trigger if they are overwhelmingly malicious (>75% defection over 30+ rounds)
    if (t > 30 && (mem.totalOpponentDefects / t) > 0.75) {
      mem.mode = "DEFEND";
    }

    if (mem.mode === "DEFEND") {
      return ["D", mem];
    }

    // --- TRUST-FIRST DECISION ENGINE ---

    // Rule A: If they cooperated last round, ALWAYS cooperate back. 
    // This locks in the R=2 mutual reward immediately.
    if (oppLast === "C") {
      return ["C", mem];
    }

    // Rule B: If they defected last round, check WHY.
    // Was their defection a justified retaliation to our own defection? 
    // (i.e., we played D last round, so them playing D now is normal).
    const wasDefectionJustified = (youLast === "D");

    if (wasDefectionJustified) {
      // They are just playing Tit-for-Tat in response to us. 
      // Do NOT hold a grudge. Forgive them and cooperate to restore the R=2 peace!
      return ["C", mem];
    }

    // Rule C: If their defection was UNPROVOKED (we played C and they betrayed us),
    // then retaliate with D to protect ourselves.
    if (mem.consecutiveOpponentDefects === 1) {
      return ["D", mem];
    }

    // Rule D: Death Spiral Breaker (Generous Forgiveness)
    // If we've been locked in mutual defection for 3 rounds, throw an olive branch.
    if (mem.consecutiveOpponentDefects >= 3) {
      mem.consecutiveOpponentDefects = 0; // Reset counter for next cycle
      return ["C", mem];
    }

    // Default fallback: Match their move
    return [oppLast, mem];

  } catch (error) {
    // Bulletproof failsafe
    return ["D", state?.memory || { mode: "DEFEND" }];
  }
}

