    move = D;
  } else if (last.you === D && last.opponent === D) {
    move = pReciprocal > pHard + 0.08 ? C : D;
  }

  if (n > 8 && pReciprocal < 0.25 && last.opponent === D) move = D;
  return [move === C || move === D ? move : D, memory || { version: 1 }];
}

export default function bot() {
	const move = "D"
	const memory = null
	return [move, memory]
}

export default state => {
  return [Math.random() < 0.6 ? "D" : "C", state.memory]
}

const outcomes: Move[] = ["C", "D"]

const bot: Bot = function(state) {
    const outcome = outcomes[Math.floor(Math.random() * outcomes.length)]

    return [outcome, null];
}

export default bot;

// flipflopper
export default function bot({ history, memory }) {
    let move
    if (memory == null || memory == "D") {
        move = "C"
    } else {
        move = "D"
    }
    memory = move

    return [move, memory]
}

export default state => {
    return ["C", state.memory]
}

export default function bot({ history, memory }) {
  memory = memory ?? { weWon: false }

  if (history.length === 0) {
    return ["D", memory] // First move
  }

  const lastOpponentMove = history.at(-1)?.opponent
  const lastMove = history.at(-1)?.you

  if (lastOpponentMove === "D") {
    memory.weWon = false
  } else {
    memory.weWon = true
  }

  if (memory.weWon) {
    return [lastMove, memory]
  } else {
    const move = lastMove === "C" ? "D" : "C"
    return [move, memory]
  }
}

export default function bot({ history }) {
  if (history.length === 0)
    return ["D", null] // Defect on the first round
  const move = history.at(-1).opponent
  if (move == "C")
    return ["D", null]
  else
    return ["C", null]
}

// "C" represents cooperation, "D" represents defection.
type Move = "C" | "D"
// A match has 2 moves, 1 by you and 1 by your opponent.
type Match = {
you: Move
opponent: Move
}
// You can put anything you want in memory, or nothing at all.
type Memory = unknown
type State = {
history: Match[] // Every round so far
memory: Memory // Whatever you saved to your memory last round
}
// A bot looks at its existing state (the history and its memory), and outputs its next move and an updated memory.
export default function bot(state: State): [Move, Memory] {
  return [state.history.slice(0,-1).opponent, null]
}
